// Evalua si el Search Records de Airtable trajo un registro previo para este Session_ID.
// alwaysOutputData=true en el nodo anterior garantiza que llegue al menos 1 item aunque no haya match.
const item = $input.first().json;
const tieneHistorial = Boolean(item && item.id && item.fields);

let datosClave = {};
try { datosClave = JSON.parse((item.fields && item.fields['Datos_Clave ']) || '{}'); } catch (e) { datosClave = {}; }

return [{
  json: {
    sessionId: $('Chat Trigger').item.json.sessionId,
    chatInput: $('Chat Trigger').item.json.chatInput,
    tiene_historial: tieneHistorial,
    airtable_record_id: tieneHistorial ? item.id : null,
    resumen_previo: tieneHistorial ? (item.fields['Resumen_Consolidado '] || '') : '',
    estado_previo: tieneHistorial ? (item.fields['Estado_del_Caso '] || 'Nuevo') : 'Nuevo',
    datos_clave_previos: datosClave,
    turno_previo: Number(datosClave.turnos || 0)
  }
}];

const raw = $input.first().json.output || $input.first().json.text || '';
const limpio = raw.replace(/```json|```/g, '').trim();
let clasificacion;
try {
  clasificacion = JSON.parse(limpio);
} catch (e) {
  clasificacion = { categoria: 'ESCALAR_HUMANO', tipo_operacion: null, zona: null, presupuesto: null, contacto: null, resumen_lead: null };
}
const categoriasValidas = ['CALIFICACION_LEAD', 'REDACCION_EMAIL', 'ESCALAR_HUMANO'];
if (!categoriasValidas.includes(clasificacion.categoria)) {
  clasificacion.categoria = 'ESCALAR_HUMANO';
}
return [{ json: clasificacion }];

const raw = $input.first().json.text || $input.first().json.output || '';
const limpio = raw.replace(/```json|```/g, '').trim();
let resumen;
try {
  resumen = JSON.parse(limpio);
} catch (e) {
  resumen = { asunto_principal: 'No se pudo generar resumen automatico', puntos_clave: [], accion_requerida: 'Revision manual del caso' };
}
return [{
  json: {
    resumen_json: resumen,
    resumen_consolidado_str: JSON.stringify(resumen),
    airtable_record_id: $('Preparar Datos para Resumen').item.json.airtable_record_id
  }
}];

